    /**
     * @param args the command line arguments
     */
    public static void main(String args[]) throws InterruptedException, ExecutionException {
       Generador f=new Generador();
       f.setSize(800,450);
        f.setTitle("Tunel");
        
        int numHilos = 10;
        Tunel tu=new Tunel();
        
        ExecutorService poolFur = Executors.newFixedThreadPool(3);
        Future<Integer>[] fFur=new Future[numHilos];
        Thread[] coches=new Thread[numHilos];
        
        Random r = new Random(System.currentTimeMillis());
      
    
        for(int i=0;i<numHilos;i++){
            if(r.nextInt(100)<50){
                coches[i]=new Coche(i,tu);
                coches[i].start();
            }else{
                fFur[i]=poolFur.submit(new Furgo(i,tu));
            }
            try {
                Thread.sleep(r.nextInt(1000, 2001));   //llegan cada 1-2 segundos
            } catch (InterruptedException ex) {
            }
        }
        
        poolFur.shutdown();
        int totalFur=0;
       for (int i = 0; i < numHilos; i++) {
           if(coches[i]!=null){
               coches[i].join();
           }
           if(fFur[i]!=null){
               totalFur=totalFur+fFur[i].get();
           }
       }
       
        System.out.println("Tiempo total de furgonetas: "+totalFur);
        try {
            Thread.sleep(3000);//espero 3 segundos para que se vea el estado final
        } catch (InterruptedException ex) {
        }
        System.exit(0);
    
    }


